using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Reflection.Emit;
using ColossalFramework;
using ColossalFramework.Plugins;
using HarmonyLib;
using HundredTiles.ExperimentalPatch;
using HundredTiles.SaveBridge;
namespace HundredTiles.Runtime
{
 public static class ReviewedCompatibility
 {
  sealed class Row {public string Type,Name,Hash;}
  static readonly Dictionary<string,List<string>> Files=new Dictionary<string,List<string>>();
  static readonly Dictionary<string,List<Row>> Rows=new Dictionary<string,List<Row>>();
  static readonly Dictionary<string,List<string>> FpsAlternatives=new Dictionary<string,List<string>>();
  static readonly HashSet<Assembly> Verified=new HashSet<Assembly>();
  static readonly Dictionary<string,List<Row>> VersionRows=new Dictionary<string,List<Row>>();
  static readonly Dictionary<Assembly,List<Row>> VerifiedRows=new Dictionary<Assembly,List<Row>>();
  static ReviewedCompatibility(){using(var stream=typeof(ReviewedCompatibility).Assembly.GetManifestResourceStream("HundredTiles.Runtime.ReviewedCompatibility.tsv"))using(var reader=new StreamReader(stream)){string line;while((line=reader.ReadLine())!=null){var p=line.Split('\t');if(p[0]=="assembly")Files.Add(p[1],new List<string>{p[2]});else if(p[0]=="assembly-alternative")Files[p[1]].Add(p[2]);else if(p[0]=="method"){List<Row> rows;if(!Rows.TryGetValue(p[1],out rows))Rows.Add(p[1],rows=new List<Row>());rows.Add(new Row{Type=p[2],Name=p[3],Hash=p[4]});}else if(p[0]=="fps-method"){string key=p[1]+"|"+p[2]+"|"+p[3];List<string> hashes;if(!FpsAlternatives.TryGetValue(key,out hashes))FpsAlternatives.Add(key,hashes=new List<string>());hashes.Add(p[4]);}else throw new InvalidOperationException("Invalid compatibility manifest.");}}LoadNetworkVersions();}
  static void LoadNetworkVersions()
  {
   using(var stream=typeof(ReviewedCompatibility).Assembly.GetManifestResourceStream("HundredTiles.Runtime.ReviewedNetworkCapacity.tsv"))
   using(var reader=new StreamReader(stream))
   {
    string line,name=null;List<Row> rows=null;
    while((line=reader.ReadLine())!=null)
    {
     var p=line.Split('\t');
     if(p[0]=="assembly")
     {
      name=p[1];if(name!="MoreNetworkCapacity" && name!="MoreNetworkCapacityRenew")throw new InvalidOperationException("Invalid network compatibility assembly.");
      Files[name].Add(p[2]);rows=new List<Row>();VersionRows.Add(name+"|"+p[2],rows);
     }
     else if(p[0]=="method" && rows!=null && p[1]==name)rows.Add(new Row{Type=p[2],Name=p[3],Hash=p[4]});
     else throw new InvalidOperationException("Invalid network compatibility manifest.");
    }
   }
  }
  static string Disk(Assembly assembly){string path=assembly.Location;if(!string.IsNullOrEmpty(path))return path;foreach(var plugin in Singleton<PluginManager>.instance.GetPluginsInfo())foreach(var loaded in plugin.GetAssemblies())if(loaded==assembly)return Path.Combine(plugin.modPath,assembly.GetName().Name=="MoreNetworkCapacity"?"MoreNetworkCapacity.Core.dll":assembly.GetName().Name+".dll");throw new InvalidOperationException("Compatibility assembly has no reviewed disk file.");}
  public static void Verify(Assembly assembly,string path){if(Verified.Contains(assembly))return;string name=assembly.GetName().Name;List<string> hashes;if(!Files.TryGetValue(name,out hashes) || !File.Exists(path) || !hashes.Contains(PlannedTranspiler.Hash(File.ReadAllBytes(path))))throw new InvalidOperationException("Reviewed compatibility version changed: "+name);List<Row> reviewed;string versionKey=name+"|"+PlannedTranspiler.Hash(File.ReadAllBytes(path));if(!VersionRows.TryGetValue(versionKey,out reviewed))reviewed=Rows[name];foreach(var row in reviewed){var type=assembly.GetType(row.Type,true);bool matched=false;foreach(var method in type.GetMethods(BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.DeclaredOnly))if(NameMatches(method.Name,row.Name) && method.GetMethodBody()!=null && BodyMatches(name,row,method)){matched=true;break;}if(!matched)throw new InvalidOperationException("Reviewed compatibility helper changed: "+row.Type+"."+row.Name);}VerifiedRows[assembly]=reviewed;Verified.Add(assembly);}
  static bool BodyMatches(string assembly,Row row,MethodInfo method){string hash=ReviewedMethod.SemanticHash(method);if(hash==row.Hash)return true;string original;if(ReviewedMethod.TryFpsLifecycleHash(method,out original) && original==row.Hash){LandscapingCompatibility.VerifyBehaviourUpdater();return true;}List<string> alternatives;if(!FpsAlternatives.TryGetValue(assembly+"|"+row.Type+"|"+row.Name,out alternatives) || !alternatives.Contains(hash))return false;LandscapingCompatibility.VerifyBehaviourUpdater();return true;}
  static bool NameMatches(string actual,string expected){return actual==expected || ((expected=="Update" || expected=="LateUpdate" || expected=="FixedUpdate") && actual=="FpsBooster"+expected);}
  static string AssemblyFor(string owner){switch(owner){case "me.tmpe":return "TrafficManager";case "MoreNetworkCapacityRenew.Comprehensive":return "MoreNetworkCapacityRenew";case "com.codex.csl.more-network-capacity":return "MoreNetworkCapacity";case "com.github.algernon-A.csl.buildingcontrol":return "BuildingControl";case "com.example.freeutilities":return "FreeUtilities";case "com.terrainlink.patches":return "TerrainLink";case "com.quaytools.patches":return "QuayTools";case "com.klyte.redirectors.CZM":return "CustomZoneMixer";case "com.github.simlor.csl.rightofway":return "RightOfWay";case "com.example.simulationguard":return "SimulationGuard";case "Will258012.FPSCamera.Continued.PassengerExchange":return "FPSCamera";case "jp.dc108.hyperload":return "HyperLoad";case "com.dc10.passengerlinebuilder":return "PassengerLineBuilder";case "com.dc10.areapobuilder":return "AreaPOBuilder";case "kunie.cs1.freeloteditor":return "FreeLotEditor";case "com.kunie.buildinglimitremoval":return "BuildingLimitRemoval";case "com.dc108.autohistoricalplop":return "AutoHistoricalPlop";case "jp.clearfpsboost":return "ClearFpsBoost";case "com.example.loadtimeremaining":return "LoadTimeRemaining";case "com.dc108.forceroadconnect":return "ForceRoadConnect";default:return null;}}
  static bool TargetAllowed(string owner,string key){if(owner=="MoreNetworkCapacityRenew.Comprehensive" && TrafficManagerSpatialCompatibility.IsSpatialTarget(key))return true;switch(owner){case "me.tmpe":return true;case "MoreNetworkCapacityRenew.Comprehensive":foreach(string type in new[]{"NetManager","CoverageManager","TransportManager","TransportLine","TransportTool","TransportNode","PathManager","DistrictManager","ZoneBlock","BuildingDecoration","NetAdjust","UnlockManager","EventManager","Building","NetTool","BuildingTool","RoadBaseAI","CarAI","VehicleAI","PassengerCarAI","BusAI","TrainAI","NetAI","RoadAI","TrainTrackAI","PedestrianPathAI","NetSegment","NetNode","NetLane","Vehicle","Citizen","CitizenInstance"})if(key.StartsWith(type+".",StringComparison.Ordinal) || key.StartsWith(type+"+",StringComparison.Ordinal))return true;return key=="InfoManager.SetActualMode" || key=="InstanceManager.Awake" || key=="RenderManager.GetInstanceIndex" || key=="RenderManager.UpdateInstance";case "com.codex.csl.more-network-capacity":return true;case "com.github.algernon-A.csl.buildingcontrol":return key=="Building.AfterTerrainUpdated" || key=="BuildingTool.SimulationStep";case "com.example.freeutilities":return key=="ElectricityManager.TryFetchElectricity" || key=="ElectricityManager.CheckElectricity" || key=="WaterManager.TryFetchWater" || key=="WaterManager.TryDumpSewage" || key=="WaterManager.CheckWater";case "com.terrainlink.patches":return key=="TerrainTool.ApplyBrush" || key=="TerrainTool.ApplyUndo" || key=="NaturalResourcesBrush.Detours.TerrainToolDetour.ApplyBrush" || key=="NaturalResourcesBrush.Detours.TerrainToolDetour.ApplyUndo";case "com.quaytools.patches":return key=="NetManager.EndRenderingImpl" || key=="TreeManager.EndRenderingImpl";case "com.klyte.redirectors.CZM":return key=="TerrainPatch.Refresh" || key=="ZoneBlock.SimulationStep";case "com.github.simlor.csl.rightofway":return key=="CarAI.CheckOtherVehicles";case "com.example.simulationguard":return key=="NaturalResourceManager.SimulationStepImpl" || key=="TerrainManager.SimulationStepImpl" || key=="ElectricityManager.SimulationStepImpl" || key=="WaterManager.SimulationStepImpl" || key=="ImmaterialResourceManager.SimulationStepImpl";case "jp.dc108.hyperload":return key=="LoadingManager.LoadLevel";case "com.dc10.passengerlinebuilder":return key=="PassengerTrainAI.LoadPassengers";case "com.dc10.areapobuilder":return key=="PrivateBuildingAI.CheckNearbyBuildingZones";case "kunie.cs1.freeloteditor":return key=="Building.CheckZoning";case "com.kunie.buildinglimitremoval":return key=="BuildingManager.Awake" || key=="RenderManager.Awake" || key=="SimulationManager+Data.Deserialize";case "com.dc108.autohistoricalplop":return key=="BuildingManager.ZonesUpdated" || key=="ZoneBlock.SimulationStep";case "jp.clearfpsboost":return key=="RenderManager.FpsBoosterLateUpdate" || key=="RenderManager.LateUpdate" || key=="FogEffect.OnRenderImage";case "com.example.loadtimeremaining":return key=="LoadingManager.LoadLevel";case "com.dc108.forceroadconnect":return key=="NetTool.MakeControlPoint";case "Will258012.FPSCamera.Continued.PassengerExchange":foreach(string type in new[]{"BusAI","CableCarAI","PassengerBlimpAI","PassengerFerryAI","PassengerHelicopterAI","PassengerPlaneAI","PassengerShipAI","PassengerTrainAI","TramAI","TrolleybusAI"})if(key==type+".LoadPassengers")return true;return false;default:return false;}}
  public static bool Allowed(string owner,MethodBase target,Patches patches){string name=AssemblyFor(owner);if(name==null || !TargetAllowed(owner,target.DeclaringType.FullName+"."+target.Name))return false;bool found=false;foreach(var pair in new[]{new KeyValuePair<string,IEnumerable<Patch>>("prefix",patches.Prefixes),new KeyValuePair<string,IEnumerable<Patch>>("postfix",patches.Postfixes),new KeyValuePair<string,IEnumerable<Patch>>("transpiler",patches.Transpilers),new KeyValuePair<string,IEnumerable<Patch>>("finalizer",patches.Finalizers)})foreach(var patch in pair.Value)if(patch.owner==owner){found=true;var method=patch.PatchMethod;if(owner=="MoreNetworkCapacityRenew.Comprehensive" && TrafficManagerSpatialCompatibility.IsSpatialTarget(target.DeclaringType.FullName+"."+target.Name) && (pair.Key!="transpiler" || method.DeclaringType.FullName!="MoreNetworkCapacityRenew.DynamicPatcher" || method.Name!="ValidationTranspiler"))return false;if(owner=="me.tmpe" && method.DeclaringType.FullName!="TrafficManager.Patch._"+target.DeclaringType.FullName+"."+target.Name+"Patch")return false;var assembly=method.Module.Assembly;if(assembly.GetName().Name!=name)return false;Verify(assembly,Disk(assembly));bool known=false;foreach(var row in VerifiedRows[assembly])if(row.Type==method.DeclaringType.FullName && row.Name==method.Name && row.Hash==ReviewedMethod.SemanticHash(method))known=true;if(!known)return false;if(owner=="com.github.algernon-A.csl.buildingcontrol" || owner=="com.klyte.redirectors.CZM"){if(pair.Key!="transpiler")return false;}else if(owner=="com.example.simulationguard"){if(pair.Key!="finalizer")return false;}else if(owner!="com.codex.csl.more-network-capacity" && owner!="MoreNetworkCapacityRenew.Comprehensive" && owner!="me.tmpe" && (pair.Key=="transpiler" || pair.Key=="finalizer"))return false;}return found;}
  public static void AddHooks(IList<HookSpec> hooks){foreach(var assembly in AppDomain.CurrentDomain.GetAssemblies()){string name=assembly.GetName().Name;if(name!="TerrainLink" && name!="RightOfWay")continue;Verify(assembly,Disk(assembly));if(name=="TerrainLink"){Add(assembly,hooks,"TerrainLink.Sync.DirtyAreas","Add","Bounds");foreach(string type in new[]{"NetworkSync","BuildingSync"}){Add(assembly,hooks,"TerrainLink.Sync."+type,"Process","Grid");Add(assembly,hooks,"TerrainLink.Sync."+type,"WorldToGrid","Grid");}}else{Add(assembly,hooks,"RightOfWay.Yielding.YieldScanner","RefreshAround","Grid");Add(assembly,hooks,"RightOfWay.Yielding.YieldScanner","CellIndex","Grid");}}}
  static void Add(Assembly assembly,IList<HookSpec> hooks,string type,string name,string adapter){var target=assembly.GetType(type,true).GetMethod(name,BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic);hooks.Add(new HookSpec{Target=target,Transpiler=typeof(ReviewedCompatibility).GetMethod(adapter)});}
  public static IEnumerable<CodeInstruction> Grid(IEnumerable<CodeInstruction> instructions){var result=new List<CodeInstruction>();int count=0;foreach(var source in instructions){var item=new CodeInstruction(source);if(item.opcode==OpCodes.Ldc_I4 || item.opcode==OpCodes.Ldc_I4_S){int value=Convert.ToInt32(item.operand);if(value==269 || value==270 || value==539 || value==540){item.opcode=OpCodes.Ldc_I4;item.operand=value==269?HundredTiles.Core.ExpandedMap.GridSize*30-1:value==270?HundredTiles.Core.ExpandedMap.GridSize*30:value==539?HundredTiles.Core.ExpandedMap.GridSize*60-1:HundredTiles.Core.ExpandedMap.GridSize*60;count++;}}result.Add(item);}if(count!=1)throw new InvalidOperationException("Reviewed compatibility grid shape changed.");return result;}
  public static IEnumerable<CodeInstruction> Bounds(IEnumerable<CodeInstruction> instructions){var result=new List<CodeInstruction>();int count=0;foreach(var source in instructions){var item=new CodeInstruction(source);if(item.opcode==OpCodes.Ldc_R4 && (float)item.operand==8640f){item.operand=(float)HundredTiles.Core.ExpandedMap.WorldMax;count++;}result.Add(item);}if(count!=2)throw new InvalidOperationException("TerrainLink world bounds shape changed.");return result;}
 }
}




